        "end_effector_0": {
            "link_name": "sensor_mount_link",
            "justification": "It serves as the mounting frame for sensors, acting as an interaction point for sensor data acquisition."
        },
        "end_effector_1": {
            "link_name": "laser_tilt_mount_link",
            "justification": "It is the attachment point for the laser tilt mechanism, functioning as an interaction frame for laser scanning."
        }
    }
}

